/* V1.6.4 · UX territorios: dibujo obligatorio al marcar + modal accesible + info compacta */
(()=>{
'use strict';
const VERSION='1.6.4';
const STATE_KEY='cec_territory_official_v150';
const DRAW_KEY='cec_territory_individual_drawings_v162';
let pendingKey=null,pendingTerritory=null,pendingTimer=null;
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>Array.from(r.querySelectorAll(s));
function readJson(k,f){try{return JSON.parse(localStorage.getItem(k)||'')||f}catch(_){return f}}
function writeJson(k,v){localStorage.setItem(k,JSON.stringify(v))}
function currentTerritory(){return String($('#t15Select')?.value||'1')}
function isDone(n,k){return !!(readJson(STATE_KEY,{})[n]?.done||{})[k]}
function labelForKey(k){const [item,side]=String(k).split('::');const names={N:'Norte',E:'Este',S:'Sur',O:'Oeste',territorio:'Territorio'};return `${item||'Tramo'} · ${names[side]||side||''}`}
function installStyle(){if($('#cecV164Style'))return;const s=document.createElement('style');s.id='cecV164Style';s.textContent=`
#cecV162Resolve{padding-bottom:24px!important;box-sizing:border-box}
#cecV162Resolve .cec-v162-sheet{height:min(86dvh,820px)!important;max-height:calc(100dvh - 38px)!important;padding:12px 14px 0!important;gap:8px!important;overflow:hidden!important}
#cecV162Resolve .cec-v162-sheet-head{flex:0 0 auto!important}
#cecV162Resolve .cec-v162-search{flex:0 0 44px!important}
#cecV162Resolve .cec-v162-resolve-list{flex:1 1 auto!important;min-height:0!important;overflow:auto!important;padding-bottom:12px!important;overscroll-behavior:contain}
#cecV162Resolve .cec-v162-sheet-actions{position:sticky!important;bottom:0!important;z-index:6!important;flex:0 0 auto!important;background:#fff!important;padding:10px 0 calc(22px + env(safe-area-inset-bottom))!important;border-top:1px solid #e0e9ed!important;box-shadow:0 -8px 18px rgba(20,55,70,.08)!important}
#cecV162Resolve .cec-v162-sheet-note{display:none!important;margin:0!important}
#cecV162Resolve .cec-v162-sheet.info-open .cec-v162-sheet-note{display:block!important;position:absolute!important;left:14px!important;right:14px!important;bottom:calc(82px + env(safe-area-inset-bottom))!important;z-index:8!important;background:#102f3d!important;color:#fff!important;border-radius:14px!important;padding:11px 13px!important;box-shadow:0 8px 24px rgba(0,0,0,.22)!important;font-size:11px!important;line-height:1.45!important}
.cec-v164-info-btn{width:40px;height:40px;border:1px solid #d7e3e8;border-radius:12px;background:#f5f9fa;color:#19546c;font-size:18px;font-weight:900;flex:0 0 auto}
.cec-v164-draw-prompt{position:sticky;top:0;z-index:12;display:none;align-items:center;gap:8px;background:#fff8e9;border:1px solid #efcf8c;color:#6b4a08;padding:9px 10px;font-size:11px;line-height:1.35}
.cec-v164-draw-prompt.show{display:flex}.cec-v164-draw-prompt strong{color:#4f3605}.cec-v164-draw-prompt span{flex:1}.cec-v164-draw-prompt button{border:0;background:#fff;border-radius:10px;padding:7px 9px;color:#795719;font-weight:900}
.cec-v164-footer-info{display:flex;justify-content:flex-end;margin:6px 0 0}.cec-v164-footer-info button{width:34px;height:34px;border:1px solid #d6e3e8;border-radius:999px;background:#f8fbfc;color:#2e6174;font-weight:900;font-size:15px}
.cec-v164-info-toast{position:fixed;left:14px;right:14px;bottom:calc(94px + env(safe-area-inset-bottom));z-index:10030;background:#123543;color:#fff;border-radius:16px;padding:12px 14px;box-shadow:0 10px 30px rgba(0,0,0,.26);font-size:11px;line-height:1.45;display:none}.cec-v164-info-toast.show{display:block}
@media(max-width:430px){#cecV162Resolve .cec-v162-sheet{height:calc(100dvh - 36px)!important;max-height:calc(100dvh - 36px)!important;border-radius:22px 22px 0 0!important}#cecV162Resolve{align-items:flex-end!important}.cec-v162-sides{grid-template-columns:repeat(2,1fr)!important}}
`;document.head.appendChild(s)}
function infoToast(text){let t=$('#cecV164InfoToast');if(!t){t=document.createElement('div');t.id='cecV164InfoToast';t.className='cec-v164-info-toast';document.body.appendChild(t)}t.textContent=text;t.classList.add('show');clearTimeout(t._tm);t._tm=setTimeout(()=>t.classList.remove('show'),5200)}
function upgradeResolver(){const r=$('#cecV162Resolve');if(!r)return;const sh=$('.cec-v162-sheet',r),head=$('.cec-v162-sheet-head',r);if(!sh||!head)return;if(!$('.cec-v164-info-btn',head)){const b=document.createElement('button');b.type='button';b.className='cec-v164-info-btn';b.textContent='i';b.setAttribute('aria-label','Información');const close=$('.cec-v162-close',head);head.insertBefore(b,close||null);b.onclick=()=>sh.classList.toggle('info-open')}if(r.classList.contains('open')&&pendingKey){const btn=$$('[data-v162-key]',r).find(x=>x.dataset.v162Key===pendingKey&&!x.disabled);if(btn){btn.click();setTimeout(()=>{$('#cecV162Apply')?.click();clearPending(false)},70)}else if(isDone(pendingTerritory,pendingKey)){setTimeout(()=>{r.classList.remove('open');clearPending(false)},50)}}}
function ensurePrompt(){let p=$('#cecV164DrawPrompt');if(p)return p;const viewer=$('#cecV162Viewer');if(!viewer)return null;p=document.createElement('div');p.id='cecV164DrawPrompt';p.className='cec-v164-draw-prompt';p.innerHTML='<span></span><button type="button">Cancelar</button>';viewer.prepend(p);$('button',p).onclick=()=>clearPending(true);return p}
function showPrompt(){const p=ensurePrompt();if(!p)return;$('span',p).innerHTML=`<strong>Dibuje este lado en el plano:</strong> ${labelForKey(pendingKey)}. Al soltar, se marcará automáticamente.`;p.classList.add('show')}
function clearPending(stopDrawing=true){clearTimeout(pendingTimer);pendingTimer=null;pendingKey=null;pendingTerritory=null;$('#cecV164DrawPrompt')?.classList.remove('show');if(stopDrawing)window.CongElCalafateTerritoriosV162?.setDrawing?.(false)}
function removeStrokeForKey(n,k){const all=readJson(DRAW_KEY,{}),arr=Array.isArray(all[n])?all[n]:[];let changed=false;all[n]=arr.flatMap(st=>{const keys=Array.isArray(st.keys)?st.keys:[];if(!keys.includes(k))return[st];changed=true;const rest=keys.filter(x=>x!==k);if(!rest.length)return[];st.keys=rest;st.newlyMarked=(st.newlyMarked||[]).filter(x=>x!==k);return[st]});if(changed){writeJson(DRAW_KEY,all);setTimeout(()=>window.CongElCalafateTerritoriosV162?.load?.(n),80)}}
function beginDrawForKey(k){const n=currentTerritory();pendingKey=k;pendingTerritory=n;window.CongElCalafateTerritoriosV162?.load?.(n);setTimeout(()=>{window.CongElCalafateTerritoriosV162?.setDrawing?.(true);showPrompt();$('#cecV162Viewer')?.scrollIntoView({behavior:'smooth',block:'start'})},120);pendingTimer=setTimeout(()=>clearPending(true),90000)}
function captureMarks(){document.addEventListener('click',e=>{const b=e.target.closest?.('[data-side-toggle],[data-tramo]');if(!b)return;const n=currentTerritory();const k=b.dataset.sideToggle||`${b.dataset.tramo}::territorio`;if(isDone(n,k)){setTimeout(()=>{if(!isDone(n,k))removeStrokeForKey(n,k)},80);return}e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();beginDrawForKey(k)},true)}
function compactNotes(){const pairs=[['.cec-local-note','.cec-territory-panel'],['.cec-map-note','.cec-map-card']];pairs.forEach(([sel,hostSel])=>{$$(sel).forEach(el=>{if(el.dataset.v164)return;el.dataset.v164='1';const text=(el.textContent||'').trim();el.style.display='none';const host=el.closest(hostSel)||el.parentElement;if(!host)return;const wrap=document.createElement('div');wrap.className='cec-v164-footer-info';const b=document.createElement('button');b.type='button';b.textContent='i';b.setAttribute('aria-label','Información');b.onclick=()=>infoToast(text);wrap.appendChild(b);host.appendChild(wrap)})});const h=$('#cecV162Help');if(h&&!h.dataset.v164){h.dataset.v164='1';const text=(h.textContent||'').trim();h.style.display='none';const head=$('.cec-v162-head');if(head&&!$('.cec-v164-info-btn.map',head)){const b=document.createElement('button');b.type='button';b.className='cec-v164-info-btn map';b.textContent='i';b.setAttribute('aria-label','Ayuda del mapa');b.onclick=()=>infoToast(text||'Dibuje sobre el lado de calle trabajado y luego confirme el tramo.');head.appendChild(b)}}}
function observe(){const mo=new MutationObserver(()=>{upgradeResolver();compactNotes();ensurePrompt()});mo.observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['class']});upgradeResolver();compactNotes();ensurePrompt()}
installStyle();captureMarks();if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',observe,{once:true});else observe();
window.CongElCalafateTerritoriosV164={version:VERSION,beginDrawForKey,clearPending};
})();
